# --- Seed adapters ---

SEED_ADAPTERS = [
    # 1. MeanPool + Linear (simplest baseline)
    """class Adapter(nn.Module):
    def __init__(self, d_model: int, output_dim: int):
        super().__init__()
        self.linear = nn.Linear(d_model, output_dim)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        pooled = hidden_states.mean(dim=1)
        return self.linear(pooled)""",

    # 2. MeanPool + MLP2 (matches best LoRA head)
    """class Adapter(nn.Module):
    def __init__(self, d_model: int, output_dim: int):
        super().__init__()
        mid = d_model // 2
        self.net = nn.Sequential(
            nn.Linear(d_model, mid),
            nn.GELU(),
            nn.Dropout(0.1),
            nn.Linear(mid, mid // 2),
            nn.GELU(),
            nn.Dropout(0.1),
            nn.Linear(mid // 2, output_dim),
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        pooled = hidden_states.mean(dim=1)
        return self.net(pooled)""",

    # 3. LastToken + MLP
    """class Adapter(nn.Module):
    def __init__(self, d_model: int, output_dim: int):
        super().__init__()
        mid = d_model // 2
        self.net = nn.Sequential(
            nn.Linear(d_model, mid),
            nn.GELU(),
            nn.Dropout(0.1),
            nn.Linear(mid, output_dim),
        )

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        last = hidden_states[:, -1, :]
        return self.net(last)""",

    # 4. Attention pooling + Linear (learnable weighted pooling)
    """class Adapter(nn.Module):
    def __init__(self, d_model: int, output_dim: int):
        super().__init__()
        self.attn_weights = nn.Linear(d_model, 1)
        self.linear = nn.Linear(d_model, output_dim)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        scores = self.attn_weights(hidden_states).squeeze(-1)
        weights = torch.softmax(scores, dim=1).unsqueeze(-1)
        pooled = (hidden_states * weights).sum(dim=1)
        return self.linear(pooled)""",

    # 5. Conv1d downsample + Linear (temporal pattern extraction)
    """class Adapter(nn.Module):
    def __init__(self, d_model: int, output_dim: int):
        super().__init__()
        ch = 128
        self.proj = nn.Linear(d_model, ch)
        self.conv = nn.Conv1d(ch, ch, kernel_size=8, stride=4)
        self.relu = nn.ReLU()
        self.linear = nn.Linear(ch, output_dim)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        x = self.proj(hidden_states)
        x = x.transpose(1, 2)
        x = self.relu(self.conv(x))
        x = x.mean(dim=2)
        return self.linear(x)""",
]

MAX_ADAPTER_PARAMS = 500_000
ALLOWED_MODULES = {"torch", "torch.nn", "torch.nn.functional", "math"}


# --- Validation ---

def validate_adapter_code(code: str, d_model: int = 768, output_dim: int = 96) -> dict:
    """Validate adapter code by exec + instantiate + dummy forward pass.

    Returns {"valid": bool, "error": str|None, "param_count": int}.
    """
    namespace = {
        "torch": torch,
        "nn": nn,
        "F": torch.nn.functional,
        "math": __import__("math"),
    }

    try:
        exec(code, namespace)
    except Exception as e:
        return {"valid": False, "error": f"exec error: {e}", "param_count": 0}

    if "Adapter" not in namespace:
        return {"valid": False, "error": "No 'Adapter' class defined", "param_count": 0}

    AdapterClass = namespace["Adapter"]
    if not (isinstance(AdapterClass, type) and issubclass(AdapterClass, nn.Module)):
        return {"valid": False, "error": "Adapter is not an nn.Module subclass", "param_count": 0}

    try:
        adapter = AdapterClass(d_model, output_dim)
    except Exception as e:
        return {"valid": False, "error": f"__init__ error: {e}", "param_count": 0}

    param_count = sum(p.numel() for p in adapter.parameters())
    if param_count > MAX_ADAPTER_PARAMS:
        return {
            "valid": False,
            "error": f"Too many params: {param_count} > {MAX_ADAPTER_PARAMS}",
            "param_count": param_count,
        }

    try:
        dummy = torch.randn(2, 512, d_model)
        with torch.no_grad():
            out = adapter(dummy)
    except Exception as e:
        return {"valid": False, "error": f"forward error: {e}", "param_count": param_count}

\mathcal{T} = \mathrm{TopK}\!\left(G_\psi(\mathbf{X}_\text{raw}),\, k\right),\;\;
\widetilde{w} = \mathrm{softmax}_{\mathcal{T}}\!\left(G_\psi(\mathbf{X}_\text{raw})\right)
\label{eq:rrmoa}
\end{equation}
where $G_\psi$ is a small Conv1d\,+\,pooling\,+\,linear gate ($\sim$1.1K params) operating directly on the raw time series, and each $\text{Expert}_k$ is a canonical adapter head. Routing is restricted to the Top-$k$ experts with the highest gate logits, so only $k$ of $K$ experts execute per sample. With $K{=}5$, $k{=}2$ we obtain $40\%$ of the dense FLOPs while retaining $63\%$ of the dense MSE gain (\S\ref{sec:topk}). The raw input preserves the temporal statistics (trend, amplitude, volatility) that RevIN strips away, enabling per-sample routing that reflects the physical characteristics of each time series window.

\textbf{Expert pool.} We maintain $K{=}5$ topologically distinct expert adapters (mean-pool, last-token, max-pool, attention-pool, Conv1d-pool), identified from structural motifs across ${\sim}1{,}200$ architectures in an LLM-guided search (Appendix~\ref{app:aas_details}). Architectural diversity is critical: replacing the five distinct heads with five identical experts (same topology, different initialization) degrades MSE by $8$--$15\%$ (Appendix~\ref{app:diversity}). Pseudocode in Algorithm~\ref{alg:rrmoa} (Appendix~\ref{app:setup}).

\section{Experiments}

\subsection{Setup}

\textbf{Datasets and tasks.} Six LTSF benchmarks (ETTh1/h2/m1/m2~\citep{zhou2021informer}, Weather, Electricity~\citep{godahewa2021monash}) with chronological splits and channel-wise normalization~\citep{nie2023patchtst}. We evaluate forecasting ($H{=}96$) and imputation ($20\%$ masked).

\textbf{Backbones.} Five backbones spanning two normalization families: instance-normalized MOMENT-small/large~\citep{goswami2024moment} (internal RevIN~\citep{kim2021revin}); LayerNorm-only Moirai~\citep{woo2024moirai} and Moirai-MoE; and Chronos~\citep{ansari2024chronos} and Timer-XL~\citep{liu2025timerxl} as no-instance-normalization negative controls (\S\ref{sec:cross_backbone}). MOMENT-small is primary. Primary results use a strictly frozen backbone; freeze-level ablations follow.

\textbf{Baselines.} Seven baselines: three fixed adapters, LoRA~\citep{hu2022lora} (108-run sweep; Appendix~\ref{app:lora_sweep}), TRACE~\citep{li2025trace}, an independent ensemble of 5 experts, AdaMix~\citep{wang2022adamix} (hidden-state MoE), full fine-tuning (all blocks unfrozen, best of 5 heads $\times$ 2 LRs), and a from-scratch DLinear~\citep{zeng2023dlinear} calibration anchor.

\textbf{Training and reproducibility.} Adam, MSE loss, 15 epochs; 5 seeds for the core grid, 3 for ablations. Backbone dimensions, full hyperparameters, and per-baseline configurations: Appendix~\ref{app:setup}. All code, raw JSON results, routing-weight logs, and a self-verification script (\texttt{verify.py}) that re-derives every numerical claim from raw data accompany the submission.

\emph{Part (ii): Frozen backbone.} When $A$ is fixed, $\dot{A} = 0$. The only dynamics are through $\mathbf{w}$:
\begin{equation*}
\dot{\mathbf{w}} = -\eta\,\frac{\partial\ell}{\partial\mathbf{w}} = -\eta\,(\ell_1 - \ell_2)\,p(1{-}p)\,\mathbf{h}
\end{equation*}
This update adjusts routing weights based on current expert performance, but does \emph{not} reshape $\mathbf{h}$ to favor one expert. Without the $A$-mediated feedback loop, there is no systematic bias toward entropy collapse: the router converges to a stable allocation reflecting the static geometry of the fixed representation space.
\end{proof}

\section{Adapter Architecture Search (AAS) Details}
\label{app:aas_details}

The AAS loop maintains a population of 20 adapters over 12 generations (${\sim}240$ evaluations, 3-epoch fitness probes). Elitism preserves the top 2; an LLM variant generates candidates in the code space $\mathcal{G}_\text{code}$. Template-based generation achieves 100\% validity (vs.\ ${\sim}75\%$ for LLM). The 5 canonical pooling heads used by RR-MoA (mean, last-token, max, attention, Conv1d) were identified as the most frequent structural motifs across the ${\sim}1{,}200$ candidate adapters explored.

\section{LoRA Sweep (Full Results)}
\label{app:lora_sweep}

